    h.settle(SETTLE);
    h.step();
    let runtime = h.app.session.execute("faces.models.list", &json!({})).unwrap()["runtime"] == true;
    let r = h.request("ui.clickWidget", json!({"id": "faces:download:sface-2021dec"}), t);
