    h.request("ui.key", json!({"key": "escape"}), t);
    h.step();
    assert!(h.app.ui.dialog.is_none());
    assert_eq!(h.app.session.execute("faces.models.downloads", &json!({})).unwrap()["downloads"], json!([]));
    let _ = std::fs::remove_dir_all(&dir);
}

